function fillFor(m: string | null, primary: Set<string>, secondary: Set<string>): string {
  if (m && primary.has(m)) return 'var(--c-green)'
  if (m && secondary.has(m)) return 'var(--c-blue)'
  return 'var(--c-body-base)'
}

function Figure({ paths, viewBox, label, primary, secondary }: {
  paths: P[]; viewBox: string; label: string; primary: Set<string>; secondary: Set<string>
}) {
  return (
    <figure className="m-0 flex-1">
      <svg viewBox={viewBox} style={{ width: '100%', height: 'auto' }} role="img" aria-label={`Muscles worked, ${label.toLowerCase()} view`}>
        {paths.map((p, i) => (
          <path key={i} d={p.d} fill={fillFor(p.m, primary, secondary)}
            stroke="rgba(120,130,120,0.22)" strokeWidth={p.m ? 1 : 0} />
        ))}
      </svg>
      <figcaption className="mt-1 text-center text-[11px] text-muted">{label}</figcaption>
    </figure>
  )
}

/** Front and back figure with worked muscles filled in. */
export function BodyMap({ primary, secondary }: { primary: Set<string>; secondary: Set<string> }) {
  return (
    <div>
      <div className="flex gap-3 rounded-2xl border border-line bg-surface px-3 py-4">
        <Figure paths={FRONT} viewBox={FRONT_VB} label="Front" primary={primary} secondary={secondary} />
        <Figure paths={BACK} viewBox={BACK_VB} label="Back" primary={primary} secondary={secondary} />
      </div>
      <div className="mt-2 flex items-center justify-center gap-4 text-[12px] text-muted">
        <span className="flex items-center gap-1.5">
          <span className="h-2.5 w-2.5 rounded-full bg-green" /> Main target
        </span>
        <span className="flex items-center gap-1.5">
          <span className="h-2.5 w-2.5 rounded-full bg-blue" /> Also worked
        </span>
      </div>
    </div>
  )
}
